import { defineExperiment } from "niceeval";
import { dbGpt } from "../agents/dbgpt.ts";

export default defineExperiment({
  description: "DB-GPT local data-analysis baseline",
  agent: dbGpt({ baseUrl: "http://127.0.0.1:5670" }),
  // Declared in configs/dbgpt-proxy-ollama.toml; not yet verified on this machine.
  model: "deepseek-r1:1.5b",
  attempts: 1,
  maxConcurrency: 1,
});
// @file ./niceeval.config.ts
import { defineConfig } from "niceeval";

export default defineConfig({
  // Add experiments/ with defineExperiment(...) to run evals.
  //
  // Judge Facts require an Eval declaration: judge: true. Configure the model here or
  // on an Experiment. A consumed Fact without a model or key becomes unavailable and
  // makes that Attempt errored. Any OpenAI-compatible /chat/completions service works;
  // the key is read from OPENAI_API_KEY unless apiKeyEnv says otherwise.
  // judge: { model: "gpt-5.4-mini" },
});

// @file ./agents/dbgpt.ts
import {
  chatCompletionEvidenceCoverage,
  defineAgent,
  turnFromChatCompletion,
} from "niceeval/adapter";
import type { Agent } from "niceeval/adapter";

type DbGptOptions = {
  baseUrl: string;
  apiKey?: string;
};

type DbGptError = {
  error?: { message?: string };
  detail?: { error?: { message?: string } };
};

export function dbGpt(options: DbGptOptions): Agent {
  return defineAgent({
    name: "dbgpt-chat-completions",
    evidenceCoverage: chatCompletionEvidenceCoverage,
    async send(input, ctx) {
      ctx.progress({ message: "waiting for DB-GPT chat completion" });
      const response = await fetch(`${options.baseUrl}/api/v2/chat/completions`, {
        method: "POST",
        headers: {
          "content-type": "application/json",
          ...(options.apiKey
            ? { authorization: `Bearer ${options.apiKey}` }
            : {}),
        },
        body: JSON.stringify({
          model: ctx.model,
          messages: [{ role: "user", content: input.text }],
          stream: false,
          incremental: false,
          conv_uid: ctx.session.id,
          chat_mode: "chat_normal",
        }),
        signal: ctx.signal,
      });

      const body = (await response.json()) as DbGptError;
      if (!response.ok) {
        const message = body.error?.message ?? body.detail?.error?.message;
        ctx.diagnostic({
          code: "dbgpt-chat-completion-failed",
          level: "error",
          message: `DB-GPT returned HTTP ${response.status}${message ? `: ${message}` : ""}`,
        });
        return { status: "failed", events: [] };
      }

      return turnFromChatCompletion(body);
    },
  });
}

// @file ./evals/local-sales-analysis.eval.ts
import { defineEval } from "niceeval";
import { pattern } from "niceeval/expect";

const salesFixture = [
  { month: "January", amount: 12 },
  { month: "February", amount: 18 },
  { month: "April", amount: 30 },
];

export default defineEval({
  description: "Analyze local sales fixture without inventing absent data",
  async test(t) {
    const total = await t.send(
      `Using this local sales fixture, calculate the total sales and briefly explain the calculation: ${JSON.stringify(salesFixture)}`,
    );
    total.succeeded().label("fixture analysis request succeeds");
    t.check(total.message, pattern(/\b60\b/)).label("reports the computed total");

    const missingMonth = await t.send(
      `Using only this local sales fixture, report the sales amount for March: ${JSON.stringify(salesFixture)}`,
    );
    missingMonth.succeeded().label("missing-data request succeeds");
    t.check(
      missingMonth.message,
      pattern(
        /(not available|insufficient data|cannot (be )?determined|not provided|no data)/i,
      ),
    ).label("declines to fabricate missing data");
  },
});

